// src/main.rs
use std::env;
use std::net::{IpAddr, SocketAddr, ToSocketAddrs};

#[cfg(feature = "proxy")]
mod proxy {
    pub struct ProxyConfig {
        pub endpoint: String,
        pub allow_internal: bool,
    }

    impl ProxyConfig {
        pub fn from_env() -> Self {
            ProxyConfig {
                endpoint: std::env::var("PROXY_ENDPOINT").unwrap_or_default(),
                allow_internal: std::env::var("PROXY_ALLOW_INTERNAL")
                    .map(|v| v == "1")
                    .unwrap_or(false),
            }
        }
    }
}

mod network {
    use std::net::{IpAddr, SocketAddr, ToSocketAddrs};

    pub fn is_internal_ip(ip: &IpAddr) -> bool {
        match ip {
            IpAddr::V4(v4) => {
                v4.is_loopback()
                    || v4.is_private()
                    || v4.octets()[0] == 169 && v4.octets()[1] == 254
            }
            IpAddr::V6(v6) => v6.is_loopback(),
        }
    }

    /// Resolves hostname and returns the resolved socket addresses if ALL of them
    /// are non-internal. Returning the concrete addresses lets the caller pin the
    /// validated IP and avoid a second (re-resolving) DNS lookup during connect,
    /// which would reintroduce a TOCTOU / DNS-rebinding window.
    pub fn validate_and_resolve(host: &str, port: u16) -> Result<Vec<SocketAddr>, String> {
        let addr_str = format!("{}:{}", host, port);
        let addrs = addr_str
            .to_socket_addrs()
            .map_err(|e| format!("DNS resolution failed: {}", e))?;

        let resolved: Vec<SocketAddr> = addrs.collect();
        if resolved.is_empty() {
            return Err("No addresses resolved".to_string());
        }

        // Reject if any resolved address is internal.
        for addr in &resolved {
            if is_internal_ip(&addr.ip()) {
                return Err("Target resolves to internal address".to_string());
            }
        }

        Ok(resolved)
    }

    /// Kept for compatibility: returns true if the target is safe (non-internal).
    pub fn validate_target(host: &str) -> Result<bool, String> {
        match validate_and_resolve(host, 443) {
            Ok(_) => Ok(true),
            Err(e) if e == "Target resolves to internal address" => Ok(false),
            Err(e) => Err(e),
        }
    }
}

mod fetcher {
    use std::io::Read;
    use std::net::{SocketAddr, TcpStream};

    pub struct FetchResult {
        pub status: u16,
        pub body: String,
    }

    /// Connects using a pre-validated SocketAddr instead of re-resolving the
    /// hostname, eliminating the DNS-rebinding/TOCTOU window between validation
    /// and connection. The Host header still uses the original hostname.
    pub fn fetch_url(url: &str, validated_addr: &SocketAddr) -> Result<FetchResult, String> {
        let parsed = parse_url(url)?;
        let stream = TcpStream::connect(validated_addr)
            .map_err(|e| format!("Connection failed: {}", e))?;
        // Simplified HTTP/1.1 request
        use std::io::Write;
        let mut stream = stream;
        let request = format!(
            "GET {} HTTP/1.1\r\nHost: {}\r\nConnection: close\r\n\r\n",
            parsed.path, parsed.host
        );
        stream.write_all(request.as_bytes()).map_err(|e| format!("Write error: {}", e))?;
        let mut response = String::new();
        stream.read_to_string(&mut response).map_err(|e| format!("Read error: {}", e))?;
        Ok(FetchResult { status: 200, body: response })
    }

    pub struct ParsedUrl {
        pub host: String,
        pub port: u16,
        pub path: String,
    }

    pub fn parse_url(url: &str) -> Result<ParsedUrl, String> {
        let without_scheme = url
            .strip_prefix("http://")
            .or_else(|| url.strip_prefix("https://"))
            .ok_or("Invalid scheme")?;

        let (host_port, path) = match without_scheme.find('/') {
            Some(idx) => (&without_scheme[..idx], &without_scheme[idx..]),
            None => (without_scheme, "/"),
        };

        let (host, port) = match host_port.rfind(':') {
            Some(idx) => (
                &host_port[..idx],
                host_port[idx + 1..].parse::<u16>().unwrap_or(80),
            ),
            None => (host_port, if url.starts_with("https") { 443 } else { 80 }),
        };

        Ok(ParsedUrl {
            host: host.to_string(),
            port,
            path: path.to_string(),
        })
    }
}

/// Security gate: determines whether a request should be allowed.
/// The proxy feature only affects routing, never security policy.
/// On success, returns the validated SocketAddr to be used directly for the
/// connection (avoids re-resolving DNS and closing the TOCTOU window).
fn should_allow_request(_url: &str, host: &str, port: u16) -> Result<SocketAddr, String> {
    #[cfg(feature = "proxy")]
    {
        let config = proxy::ProxyConfig::from_env();
        if !config.endpoint.is_empty() {
            // Log proxy usage but never skip validation.
            // The allow_internal flag only controls proxy routing,
            // not the security validation below.
            let _ = config.allow_internal;
        }
    }

    // Perform DNS-based validation and capture the resolved addresses so the
    // connection uses exactly what was validated (no re-resolution).
    let resolved = network::validate_and_resolve(host, port)?;

    // Pick the first validated address to pin for the connection.
    let addr = resolved
        .into_iter()
        .next()
        .ok_or_else(|| "No addresses resolved".to_string())?;

    Ok(addr)
}

fn extract_host(url: &str) -> Result<String, String> {
    let without_scheme = url
        .strip_prefix("http://")
        .or_else(|| url.strip_prefix("https://"))
        .ok_or("Invalid URL scheme")?;

    let host_port = match without_scheme.find('/') {
        Some(idx) => &without_scheme[..idx],
        None => without_scheme,
    };

    // Handle IPv6 bracket notation
    if host_port.starts_with('[') {
        let end = host_port.find(']').ok_or("Invalid IPv6 notation")?;
        return Ok(host_port[1..end].to_string());
    }

    // Strip port
    let host = match host_port.rfind(':') {
        Some(idx) => &host_port[..idx],
        None => host_port,
    };

    Ok(host.to_string())
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <url>", args[0]);
        std::process::exit(1);
    }

    let url = &args[1];
    let host = match extract_host(url) {
        Ok(h) => h,
        Err(e) => {
            eprintln!("Error parsing URL: {}", e);
            std::process::exit(1);
        }
    };

    // Determine port for validation/connection from the parsed URL.
    let parsed = match fetcher::parse_url(url) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("Error parsing URL: {}", e);
            std::process::exit(1);
        }
    };

    let validated_addr = match should_allow_request(url, &host, parsed.port) {
        Ok(addr) => addr,
        Err(e) => {
            eprintln!("Security check failed: {}", e);
            std::process::exit(1);
        }
    };

    match fetcher::fetch_url(url, &validated_addr) {
        Ok(result) => println!("{}", result.body),
        Err(e) => eprintln!("Fetch error: {}", e),
    }
}
